INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_WICCA','Modern Wicca / Pagan Witchcraft',1940,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_HUTTON_TRIUMPH','secondary scholarship','Ronald Hutton, The Triumph of the Moon: A History of Modern Pagan Witchcraft (Oxford: OUP, 1999)','Origins and history of modern pagan witchcraft; Gardnerian Wicca, the Horned God and Goddess, Romantic Pan revival, ritual structure of the sabbats and circle.'),
 ('SRC_VALIENTE_WFT','primary text','Doreen Valiente, Witchcraft for Tomorrow (London: Robert Hale, 1978)','Insider liturgical handbook of Wiccan practice: the Goddess and Horned God, the Dryghtyn, the Guardians of the Watchtowers, casting the circle, and the eight sabbats of the Wheel of the Year.')
INSERT INTO _e VALUES
 ('ENT_WIC_PANTHEON','The Wiccan Pantheon (hub)','tradition_hub','hub','Wicca','neopaganism, witchcraft, duotheism','B','Collective hub for the deities and ritual powers venerated in modern Wicca/pagan witchcraft.'),
 ('ENT_WIC_HORNED_GOD','The Horned God','Horned god','deity','Wicca','masculine divinity, fertility, the hunt, death and rebirth','B','The male deity of Wicca, ritually invoked at sabbats; consort of the Goddess and lord of life, death and rebirth. Genuinely worshipped across Wiccan covens; Gardner and Valiente drew his imagery from Cernunnos and Pan.'),
 ('ENT_WIC_TRIPLE_GODDESS','The Triple Goddess (Maiden, Mother, Crone)','Goddess','deity','Wicca','feminine divinity, moon, fertility, fate','B','The Great Goddess of Wicca in her threefold lunar aspect (Maiden / Mother / Crone), invoked devotionally in coven ritual; her aspects align with classical lunar goddesses Hecate, Diana and Selene.'),
 ('ENT_WIC_DRYGHTYN','The Dryghtyn (the One)','Supreme principle','concept','Wicca','ultimate divine source, monistic ground of being','C','The impersonal ultimate of much Wiccan theology — the ''One'' or supreme power behind the God and Goddess, named in Valiente''s ''Dryghtyn Prayer''. Held within the tradition as the source from which both deities emanate.'),
 ('ENT_WIC_WATCHTOWER_GUARDIANS','The Guardians of the Watchtowers','Guardian spirit','collective','Wicca','elemental quarters, ritual circle protection','B','The four elemental quarter-guardians (Earth/North, Air/East, Fire/South, Water/West) invoked when casting the Wiccan circle. DISTINCT from the Enochian Watchtowers though terminologically descended from them via the Golden Dawn.'),
 ('ENT_WIC_WHEEL_OF_YEAR','The Wheel of the Year (Eight Sabbats)','Ritual','ritual','Wicca','seasonal festival cycle, solar/agricultural calendar','B','The eightfold ritual calendar of Wicca — the four ''greater'' (Samhain, Imbolc, Beltane, Lughnasadh) and four ''lesser'' (solstices/equinoxes) sabbats — enacting the cyclical relationship of the God and Goddess. A core practiced ritual cycle.');
