INSERT INTO entity_sources (entity_id,source_id,evidence_type,source_note)
INSERT INTO _p VALUES
 ('ENT_WIC_PANTHEON','PER_WICCA','Collective hub for the deities and ritual powers venerated in modern Wicca/pagan witchcraft.'),
 ('ENT_WIC_HORNED_GOD','PER_WICCA','The male deity of Wicca, ritually invoked at sabbats; consort of the Goddess and lord of life, death and rebirth. Genuinely worshipped across Wiccan covens; Gardner and Valiente drew his imagery from Cernunnos and Pan.'),
 ('ENT_WIC_TRIPLE_GODDESS','PER_WICCA','The Great Goddess of Wicca in her threefold lunar aspect (Maiden / Mother / Crone), invoked devotionally in coven ritual; her aspects align with classical lunar goddesses Hecate, Diana and Selene.'),
 ('ENT_WIC_DRYGHTYN','PER_WICCA','The impersonal ultimate of much Wiccan theology — the ''One'' or supreme power behind the God and Goddess, named in Valiente''s ''Dryghtyn Prayer''. Held within the tradition as the source from which both deities emanate.'),
 ('ENT_WIC_WATCHTOWER_GUARDIANS','PER_WICCA','The four elemental quarter-guardians (Earth/North, Air/East, Fire/South, Water/West) invoked when casting the Wiccan circle. DISTINCT from the Enochian Watchtowers though terminologically descended from them via the Golden Dawn.'),
 ('ENT_WIC_WHEEL_OF_YEAR','PER_WICCA','The eightfold ritual calendar of Wicca — the four ''greater'' (Samhain, Imbolc, Beltane, Lughnasadh) and four ''lesser'' (solstices/equinoxes) sabbats — enacting the cyclical relationship of the God and Goddess. A core practiced ritual cycle.');
INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_WIC_HORNED_GOD','member_of','ENT_WIC_PANTHEON','high','The Horned God is a core deity of the Wiccan pantheon hub.'),
 ('ENT_WIC_TRIPLE_GODDESS','member_of','ENT_WIC_PANTHEON','high','The Triple Goddess is the principal female deity of the Wiccan pantheon hub.'),
 ('ENT_WIC_DRYGHTYN','member_of','ENT_WIC_PANTHEON','medium','The Dryghtyn / ''the One'' belongs to the Wiccan theological collective as its ultimate principle.'),
 ('ENT_WIC_WATCHTOWER_GUARDIANS','member_of','ENT_WIC_PANTHEON','medium','The quarter-guardians are part of the Wiccan ritual-cosmological roster collected under the hub.'),
 ('ENT_WIC_WHEEL_OF_YEAR','member_of','ENT_WIC_PANTHEON','medium','The Wheel of the Year is the central ritual cycle of the tradition grouped under the hub.'),
 ('ENT_WIC_HORNED_GOD','emanates_from','ENT_WIC_DRYGHTYN','medium','In Wiccan theology the God and Goddess emanate from the impersonal Dryghtyn / the One.'),
 ('ENT_WIC_TRIPLE_GODDESS','emanates_from','ENT_WIC_DRYGHTYN','medium','The Goddess is understood within the tradition as a manifestation emanating from the supreme Dryghtyn.'),
 ('ENT_WIC_HORNED_GOD','consort_of','ENT_WIC_TRIPLE_GODDESS','high','Wiccan duotheism pairs the Horned God and the Goddess as divine consorts whose union drives the seasonal cycle.'),
 ('ENT_WIC_WHEEL_OF_YEAR','associated_with','ENT_WIC_HORNED_GOD','high','The sabbats of the Wheel of the Year dramatize the birth, life, death and rebirth of the Horned God.'),
 ('ENT_WIC_WHEEL_OF_YEAR','associated_with','ENT_WIC_TRIPLE_GODDESS','high','The Wheel of the Year tracks the Goddess through her Maiden/Mother/Crone aspects across the seasons.'),
 ('ENT_WIC_WATCHTOWER_GUARDIANS','protects','ENT_WIC_PANTHEON','medium','The Guardians of the Watchtowers are invoked to ward and protect the cast ritual circle in which the deities are worshipped.'),
 ('ENT_WIC_HORNED_GOD','reception_of','ENT_CEL_CERNUNNOS','high','Gardner and Valiente explicitly drew the Wiccan Horned God''s imagery and name from the antlered Gaulish god Cernunnos (Hutton, Triumph of the Moon).'),
 ('ENT_WIC_HORNED_GOD','reception_of','ENT_PAN','high','The Horned God''s goat-horned, ithyphallic nature-deity persona derives from the 19th-century Romantic revival of the Greek Pan that fed directly into Wicca (Hutton).'),
 ('ENT_WIC_TRIPLE_GODDESS','aligned_with','ENT_HECATE','high','The Crone aspect of the Wiccan Triple Goddess is identified with the classical lunar/chthonic Hecate.'),
 ('ENT_WIC_TRIPLE_GODDESS','aligned_with','ENT_ROM_DIANA','high','The Maiden/huntress aspect of the Triple Goddess aligns with Diana, central to the Romantic ''Dianic'' witch-cult lineage absorbed by Wicca.'),
 ('ENT_WIC_TRIPLE_GODDESS','aligned_with','ENT_SELENE','medium','The lunar Mother aspect of the Triple Goddess aligns with the Greek moon goddess Selene, the full-moon face of the triad.'),
 ('ENT_WIC_WATCHTOWER_GUARDIANS','reception_of','ENT_REN_WATCHTOWERS','medium','The Wiccan quarter-guardians inherit the ''Watchtower'' terminology from the Enochian Great Table via the Golden Dawn, while functioning as distinct elemental guardians.');
